mapper.select:
SELECT t.id, t.mold_id, m.mold_code, m.name AS mold_name, t.sensor_location, t.temperature, t.operator_id, u.real_name AS operator_name, t.operation_time, t.created_at, t.description FROM temperature_logs t LEFT JOIN molds m ON t.mold_id = m.id LEFT JOIN users u ON t.operator_id = u.id
AND t.mold_id = #{moldId}
AND ( m.name LIKE CONCAT('%', #{keyword}, '%') OR m.mold_code LIKE CONCAT('%', #{keyword}, '%') )
AND t.sensor_location LIKE CONCAT('%', #{sensorLocation}, '%')
AND t.operator_id = #{operatorId}
AND t.operation_time >= #{startTime}
AND t.operation_time <= #{endTime}
ORDER BY t.operation_time DESC, t.created_at DESC

SELECT mold_id FROM temperature_logs
WHERE operation_time >= #{since}
GROUP BY mold_id
HAVING

    MAX(temperature) > #{valueThreshold}
    MAX(temperature) >= #{valueThreshold}
    MAX(temperature) < #{valueThreshold}
    MAX(temperature) <= #{valueThreshold}
    AVG(temperature) > #{valueThreshold}
    AVG(temperature) >= #{valueThreshold}
    AVG(temperature) < #{valueThreshold}
    AVG(temperature) <= #{valueThreshold}
    1=0

SELECT mold_id FROM temperature_logs
WHERE operation_time >= #{since}
AND

    temperature > #{valueThreshold}
    temperature >= #{valueThreshold}
    temperature < #{valueThreshold}
    temperature <= #{valueThreshold}
    1=0

GROUP BY mold_id
HAVING COUNT(1) >= #{countThreshold}
